class MyCalendarTwo {
    private final List<int[]> bookings=new ArrayList<>(),overlaps=new ArrayList<>();
    public MyCalendarTwo(){
    }
    public boolean book(int startTime,int endTime){
        for(int[] overlap:overlaps)if(Math.max(startTime,overlap[0])<Math.min(endTime,overlap[1]))return false;
        for(int[] booking:bookings){
            int left=Math.max(startTime,booking[0]),right=Math.min(endTime,booking[1]);
            if(left<right)overlaps.add(new int[]{
                left,right
            });
        }
        bookings.add(new int[]{
            startTime,endTime
        });
        return true;
    }
}

code.kotlin:
class MyCalendarTwo {
    private val bookings=mutableListOf<IntArray>();
    private val overlaps=mutableListOf<IntArray>();
    fun book(startTime:Int,endTime:Int):Boolean{
        for(overlap in overlaps)if(maxOf(startTime,overlap[0])<minOf(endTime,overlap[1]))return false;
        for(booking in bookings){
            val left=maxOf(startTime,booking[0]);
            val right=minOf(endTime,booking[1]);
            if(left<right)overlaps.add(intArrayOf(left,right))
        };
        bookings.add(intArrayOf(startTime,endTime));
        return true
    }
}

